 static void window(Store s,String w){fixture(s);if(w.equals("pm")){JSONObject cfg=s.config();Store.put(cfg,"amStart","00:00");Store.put(cfg,"amEnd","00:01");Store.put(cfg,"pmStart","00:01");Store.put(cfg,"pmEnd","23:59");s.saveConfig(cfg);}s.prefs.edit().putBoolean("autostartConfirmed",true).putBoolean("firstGuidePending",false).commit();s.enabled(true);s.day(new JSONObject());s.round(new JSONObject());}
