  final int[] reads={0};Context deniedPermission=new ContextWrapper(c){@Override public Context getApplicationContext(){return this;}@Override public int checkSelfPermission(String permission){return android.Manifest.permission.ACCESS_FINE_LOCATION.equals(permission)?android.content.pm.PackageManager.PERMISSION_DENIED:super.checkSelfPermission(permission);}@Override public Object getSystemService(String name){if(Context.WIFI_SERVICE.equals(name))reads[0]++;return super.getSystemService(name);}};Planner.checkNow(deniedPermission);check(reads[0]==0&&s.round().length()==0,"missing Wi-Fi permission performs no SSID read");
