  new AlarmReceiver().onReceive(c,new Intent("ALARM").putExtra("token","repeat_am"));check(s.pending().length()==0,"old five minute alarm ignored");
  window(s,"am");ready(s);sample(c,true);check(s.pending().has("am"),"AM pending before adjacent window change");JSONObject adjacent=s.config();Store.put(adjacent,"amEnd","00:01");Store.put(adjacent,"pmStart","00:01");Store.put(adjacent,"pmEnd","23:59");s.saveConfig(adjacent);sample(c,false);check(s.pending().length()==0&&"pm".equals(s.round().optString("key")),"window change cancels old alert before starting next minute");
  window(s,"pm");sample(c,false);check(s.pending().length()==0,"PM no startup alert");ready(s);sample(c,false);check(s.pending().has("pm"),"PM disconnected/failed read node alerts");long pm=s.pending().optJSONObject("pm").optLong("due");Planner.complete(c,"pm",pm-1);check(s.pending().has("pm"),"stale notification cannot confirm");sample(c,true);check(s.pending().length()==0,"PM reconnect clears pending immediately");Planner.complete(c,"pm",pm);check(!s.day().optBoolean("pmDone"),"old notification cannot complete cleared round");ready(s);sample(c,true);check(s.pending().length()==0,"PM connected node silent");ready(s);sample(c,false);Planner.complete(c,"pm",s.pending().optJSONObject("pm").optLong("due"));check(s.day().optBoolean("pmDone")&&!s.day().optBoolean("amDone"),"PM notification confirmation affects only PM");
  Planner.attendanceUndo(c,"pm");check(s.pending().length()==0&&s.round().optLong("nextAt")>=System.currentTimeMillis()+59000,"PM undo resets old pending and timer");JSONObject cfg=s.config();Store.put(cfg.optJSONObject("calendar"),s.today(),false);s.saveConfig(cfg);sample(c,false);check(s.round().length()==0&&s.pending().length()==0,"nonwork day clears everything");
  window(s,"pm");ready(s);sample(c,false);new AlarmReceiver().onReceive(c,new Intent("PAUSE"));check(!s.enabled()&&s.pending().length()==0&&s.round().length()==0,"total switch cancels everything");
  window(s,"am");cfg=s.config();for(String k:new String[]{"amStart","amEnd","pmStart","pmEnd"})Store.put(cfg,k,"");s.saveConfig(cfg);sample(c,true);check(s.pending().length()==0&&s.round().length()==0,"empty windows never monitor");
